-- S2-02: an organization name is unique per owner, ignoring case and outer
-- spaces. The statements marked "hand-written" are not generated by Prisma.

-- Hand-written: add the owner nullable, backfill it from the owner membership,
-- then make it required (the generated ADD COLUMN ... NOT NULL fails on rows).
ALTER TABLE "organization" ADD COLUMN "ownerId" TEXT;

UPDATE "organization" o
SET "ownerId" = m."userId"
FROM "organization_member" m
WHERE m."organizationId" = o."id" AND m."role" = 'owner';

ALTER TABLE "organization" ALTER COLUMN "ownerId" SET NOT NULL;

-- CreateIndex
CREATE INDEX "organization_ownerId_idx" ON "organization"("ownerId");

-- AddForeignKey
ALTER TABLE "organization" ADD CONSTRAINT "organization_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "user"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written: stored names are trimmed and non-empty; the unique index makes
-- concurrent creates of "Tábor" / "tábor" / " Tábor " race-safe.
UPDATE "organization" SET "name" = btrim("name");

-- Existing duplicates (same owner, same name ignoring case) keep the oldest
-- row's name. Every later one is renamed one by one to "<name> (n)" with the
-- smallest n >= 2 that no other row of that owner uses (renames made earlier in
-- the loop count), so the repair can never collide, e.g. with a row that is
-- already called "Foo (2)".
DO $$
DECLARE
  dup RECORD;
  suffix INTEGER;
BEGIN
  FOR dup IN
    SELECT "id", "ownerId", "name"
    FROM (
      SELECT "id", "ownerId", "name", row_number() OVER (
        PARTITION BY "ownerId", lower("name") ORDER BY "createdAt", "id"
      ) AS rn
      FROM "organization"
    ) ranked
    WHERE rn > 1
    ORDER BY "ownerId", "id"
  LOOP
    suffix := 2;
    WHILE EXISTS (
      SELECT 1 FROM "organization" o
      WHERE o."ownerId" = dup."ownerId"
        AND o."id" <> dup."id"
        AND lower(o."name") = lower(left(dup."name", 190) || ' (' || suffix || ')')
    ) LOOP
      suffix := suffix + 1;
    END LOOP;
    UPDATE "organization"
    SET "name" = left(dup."name", 190) || ' (' || suffix || ')'
    WHERE "id" = dup."id";
  END LOOP;
END $$;

ALTER TABLE "organization"
  ADD CONSTRAINT "organization_name_trimmed_check"
  CHECK ("name" <> '' AND "name" = btrim("name"));

CREATE UNIQUE INDEX "organization_owner_name_key"
  ON "organization" ("ownerId", lower("name"));
